<script setup>
import{Head,Link,router,usePage}from'@inertiajs/vue3';import{computed,ref}from'vue';
const props=defineProps({status:String,authenticated:Boolean,onboardingComplete:Boolean,event:Object});const busy=ref(false),page=usePage();
const copy={valid:['You’re invited','Review the event details and confirm your access.'],already_accepted:['You already joined','Your event access is active.'],expired:['Invitation expired','Ask the photographer for a new invitation.'],revoked:['Invitation revoked','This invitation is no longer active.'],invalid:['Invitation not found','Check the link or request a new invitation.'],unauthorized_account:['This account cannot join','Contact the photographer if you believe this is a mistake.'],event_unavailable:['Event unavailable','This event is currently unavailable.'],unavailable:['Invitation unavailable','This invitation has reached its usage limit.'],session_expired:['Session expired','Open the original invitation again.']}[props.status]||['Invitation unavailable','Please request a new invitation.'];
function accept(){busy.value=true;router.post(page.url,{}, {onFinish:()=>busy.value=false})}function decline(){router.post(`${page.url}/decline`)}</script>
<template><Head title="Event invitation"/><main class="min-h-screen bg-ink text-white"><div class="mx-auto flex min-h-screen max-w-6xl items-center px-5 py-12"><section class="grid w-full overflow-hidden rounded-3xl bg-white text-ink shadow-2xl lg:grid-cols-[1.15fr_.85fr]"><div class="relative min-h-72 bg-gradient-to-br from-indigo via-indigo/70 to-coral/70 p-8 text-white md:p-12"><p class="font-display text-2xl font-bold">LensPic</p><div class="mt-24"><p class="text-xs font-bold uppercase tracking-[.2em] text-white/60">Private event invitation</p><h1 class="mt-4 font-display text-4xl font-bold">{{event?.name||'Event invitation'}}</h1><p v-if="event" class="mt-4 text-white/70">{{event.photographer}}<span v-if="event.event_date"> · {{event.event_date}}</span></p></div></div><div class="flex flex-col justify-center p-8 md:p-12"><div :class="['mb-5 h-2 w-14',status==='valid'||status==='already_accepted'?'bg-indigo':'bg-coral']"></div><h2 class="font-display text-3xl font-bold">{{copy[0]}}</h2><p class="mt-3 text-sm leading-6 text-black/55">{{copy[1]}}</p><dl v-if="event&&(status==='valid'||status==='already_accepted')" class="mt-7 space-y-3 border-y border-black/5 py-5 text-sm"><div class="flex justify-between gap-4"><dt class="text-black/45">Access</dt><dd class="font-semibold">{{event.access}}</dd></div><div v-if="event.location" class="flex justify-between gap-4"><dt class="text-black/45">Location</dt><dd class="font-semibold">{{event.location}}</dd></div></dl><div v-if="status==='valid'" class="mt-7 space-y-3"><template v-if="authenticated&&onboardingComplete"><button class="btn-primary w-full" :disabled="busy" @click="accept">{{busy?'Confirming…':'Accept invitation'}}</button><button class="btn-muted w-full" @click="decline">Decline</button></template><template v-else><Link href="/register" class="btn-primary w-full">Continue securely</Link><Link href="/login" class="btn-muted w-full">I already have an account</Link><p class="text-xs text-black/40">Your invitation is retained only in this browser session while you authenticate.</p></template></div><Link v-else-if="status==='already_accepted'" :href="`/groups/${event?.id||''}`" class="btn-primary mt-7">Open event</Link><Link v-else href="/join-group" class="btn-muted mt-7">Enter another invitation code</Link></div></section></div></main></template>
